import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { t, request } from '../util';
import { link } from './format';

/** Pages that share one title or one description. */
export default class Duplicates extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.kind = 'title';
    this.load();
  }
  load() {
    this.groups = null;
    request('GET', '/duplicates', null, {
      kind: this.kind
    }).then(response => {
      this.groups = response.data;
      m.redraw();
    });
  }
  view() {
    return m("div", null, m("div", {
      className: "SurveyorToolbar"
    }, ['title', 'description'].map(kind => m(Button, {
      className: `Button ${this.kind === kind ? 'Button--primary' : ''}`,
      onclick: () => (this.kind = kind, this.load())
    }, t(`duplicates.${kind}`)))), m("p", {
      className: "helpText"
    }, t('duplicates.help')), this.groups === null ? m(LoadingIndicator, null) : null, this.groups && this.groups.length === 0 ? m("p", {
      className: "SurveyorEmpty"
    }, t('duplicates.empty')) : null, (this.groups || []).map(group => m("div", {
      className: "SurveyorGroup"
    }, m("div", {
      className: "SurveyorGroup-head"
    }, m("strong", null, group.text || '–'), " ", m("span", {
      className: "SurveyorMuted"
    }, t('duplicates.count', {
      count: group.total
    }))), m("ul", null, group.pages.map(page => m("li", null, link(page.url, page.path)))))));
  }
}
flarum.reg.add('ernestdefoe-surveyor', 'admin/workspace/Duplicates', Duplicates);